/* ==========================================================================
   SKYNET SOLUSINDO - STYLING LANDING PAGE MODERN JARINGAN KOMPUTER SURAKARTA
   Tema Warna: Hitam (#090d16), Biru Tua (#1e3a8a, #0f172a), Abu-abu (#94a3b8, #334155)
   Fitur: Font Glowing & Animasi Interaktif, Navigasi Halaman Multi-View (Next/Back)
   ========================================================================== */
/* ══════════════════════════════════════════════════════════════════════
   SKYNET SOLUSINDO — LANDING PAGE PREMIUM v2.0
   Tema: Profesional · Elegan · Modern
   Palet: Midnight Navy (#080f1e) · Cobalt Blue (#1a56db) · Cyan (#00d4ff)
          Slate (#94a3b8) · Gold (#f59e0b) · Deep Black (#040810)
   ══════════════════════════════════════════════════════════════════════ */

/* 1. VARIABEL WARNA & SISTEM DESAIN */
/* ── 1. CSS CUSTOM PROPERTIES (TOKEN DESAIN) ─────────────────────── */
:root {
    /* Palet Warna: Hitam & Background Gelap */
    --color-black-deep: #070a12;
    --color-black-main: #0b0f19;
    --color-surface-dark: #0f172a;

    /* Palet Warna: Biru Tua & Aksen Jaringan */
    --color-navy-dark: #0f1f3d;
    --color-navy-main: #172554;
    --color-navy-light: #1e3a8a;
    --color-blue-accent: #2563eb;
    --color-blue-bright: #3b82f6;
    --color-cyan-glow: #38bdf8;

    /* Palet Warna: Abu-abu Santai & Elegan */
    --color-gray-dark: #1e293b;
    --color-gray-border: #334155;
    --color-gray-muted: #94a3b8;
    --color-gray-light: #cbd5e1;
    --color-white: #f8fafc;

    /* Efek Glow & Shadow */
    --glow-cyan: 0 0 15px rgba(56, 189, 248, 0.6), 0 0 30px rgba(37, 99, 235, 0.4);
    --glow-cyan-subtle: 0 0 10px rgba(56, 189, 248, 0.4);
    --glow-box: 0 10px 30px -5px rgba(2, 6, 23, 0.8), 0 0 20px rgba(30, 58, 138, 0.3);
    --glow-card-hover: 0 15px 35px -5px rgba(2, 6, 23, 0.9), 0 0 25px rgba(56, 189, 248, 0.35);
    /* Backgrounds */
    --bg-deepest: #030711;
    --bg-dark: #060d1a;
    --bg-card: #0c1628;
    --bg-card-alt: #0e1c35;
    --bg-surface: #111f38;
    --bg-alt: #0a1428;

    /* Transisi Halus */
    --transition-fast: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    --transition-smooth: 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    --transition-slow: 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Blue Spectrum */
--blue-900: #0d1b3e;
--blue-800: #1a2f5e;
--blue-700: #1a56db;
--blue-600: #2563eb;
--blue-500: #3b82f6;
--blue-400: #60a5fa;

/* 2. RESET & DASAR */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Accent Cyan */
--cyan: #00d4ff;
--cyan-dim: rgba(0, 212, 255, 0.12);
--cyan-glow: rgba(0, 212, 255, 0.4);

html {
    scroll-behavior: smooth;
    font-size: 16px;
    background-color: var(--color-black-deep);
}

/* Accent Gold */
--gold: #f59e0b;
--gold-dim: rgba(245, 158, 11, 0.15);

body {
    font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background-color: var(--color-black-main);
    color: var(--color-gray-light);
    line-height: 1.65;
    overflow-x: hidden;
    position: relative;
    min-height: 100vh;
}

/* Accent Green */
--green: #22c55e;
--green-dim: rgba(34, 197, 94, 0.12);

/* Background Ambient Lighting Glow */
.ambient-glow {
    position: fixed;
    border-radius: 50%;
    filter: blur(120px);
    pointer-events: none;
    z-index: 0;
    opacity: 0.45;
}

/* Accent Purple */
--purple: #a855f7;
--purple-dim: rgba(168, 85, 247, 0.12);

.glow-top {
    width: 650px;
    height: 450px;
    background: radial-gradient(circle, rgba(30, 58, 138, 0.8), rgba(56, 189, 248, 0.3), transparent 70%);
    top: -150px;
    left: 20%;
}

/* Text */
--text-primary: #f1f5f9;
--text-secondary: #94a3b8;
--text-muted: #64748b;
--text-white: #ffffff;

.glow-bottom {
    width: 600px;
    height: 500px;
    background: radial-gradient(circle, rgba(23, 37, 84, 0.9), rgba(56, 189, 248, 0.2), transparent 70%);
    bottom: 5%;
    right: -100px;
}

/* Borders */
--border: rgba(148, 163, 184, 0.1);
--border-blue: rgba(0, 212, 255, 0.25);
--border-hover: rgba(0, 212, 255, 0.5);

/* Subtle Network Grid Overlay */
.grid-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image:
        linear-gradient(to right, rgba(255, 255, 255, 0.02) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(255, 255, 255, 0.02) 1px, transparent 1px);
    background-size: 50px 50px;
    pointer-events: none;
    z-index: 0;
}

/* Shadows & Glows */
--shadow-card: 0 20px 40px rgba(0, 0, 0, 0.6);
--shadow-glow: 0 0 40px rgba(0, 212, 255, 0.3);
--shadow-btn: 0 8px 32px rgba(26, 86, 219, 0.4);

.container {
    width: 90%;
    max-width: 1200px;
    margin: 0 auto;
    position: relative;
    z-index: 1;
}

/* Typography */
--font-body: 'Inter',
system-ui,
-apple-system,
sans-serif;
--font-head: 'Syne',
'Inter',
sans-serif;

/* 3. TIPOGRAFI & EFEK CAHAYA FONT (GLOW FONT) */
h1,
h2,
h3,
h4 {
    color: var(--color-white);
    font-weight: 700;
    line-height: 1.25;
}

/* Spacing */
--r-sm: 10px;
--r-md: 16px;
--r-lg: 24px;
--r-xl: 32px;

.text-gradient {
    background: linear-gradient(135deg, #ffffff 15%, var(--color-cyan-glow) 60%, var(--color-blue-bright) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    /* Transitions */
    --ease: cubic-bezier(0.16, 1, 0.3, 1);
    --t-fast: 0.2s var(--ease);
    --t-med: 0.4s var(--ease);
    --t-slow: 0.7s var(--ease);
}

.text-highlight {
    color: var(--color-cyan-glow);
    text-shadow: 0 0 12px rgba(56, 189, 248, 0.5);
}

/* ── 2. RESET & BASE ──────────────────────────────────────────────── */
*,
*::before,
*::after {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* EFEK KHUSUS: FONT YANG BISA DIKLIK ADA PENCAHAYAAN & ANIMASI */
.glow-interactive,
.glow-font-btn,
.glow-link {
    cursor: pointer;
    transition: all var(--transition-smooth);
    position: relative;
    user-select: none;
}

html {
    scroll-behavior: smooth;
    font-size: 16px;
    background: var(--bg-deepest);
}

/* Efek Pancaran Cahaya Teks saat Hover & Fokus */
.glow-interactive:hover,
.glow-font-btn:hover,
.glow-link:hover {
    color: #ffffff !important;
    text-shadow: var(--glow-cyan) !important;
    transform: translateY(-2px);

    body {
        font-family: var(--font-body);
        background: var(--bg-dark);
        color: var(--text-secondary);
        line-height: 1.65;
        overflow-x: hidden;
        -webkit-font-smoothing: antialiased;
    }

    /* Animasi saat font/elemen interaktif diklik (Flash of Light & Ripple) */
    .glow-interactive:active,
    .glow-font-btn:active,
    .glow-link:active {
        transform: scale(0.97) translateY(0);
        text-shadow: 0 0 25px rgba(56, 189, 248, 1), 0 0 45px rgba(59, 130, 246, 0.9) !important;
    }

    img {
        display: block;
        max-width: 100%;
        height: auto;
    }

    a {
        text-decoration: none;
        color: inherit;
    }

    button {
        font-family: inherit;
        cursor: pointer;
        border: none;
        outline: none;
    }

    ul,
    ol {
        list-style: none;
    }

    input,
    select,
    textarea {
        font-family: inherit;
    }

    /* Efek Pulsasi Cahaya Halus */
    @keyframes fontLightPulse {

        0%,
        100% {
            text-shadow: 0 0 8px rgba(56, 189, 248, 0.5);
        }

        50% {
            text-shadow: 0 0 18px rgba(56, 189, 248, 0.9), 0 0 30px rgba(37, 99, 235, 0.6);
        }

        /* ── 3. PARTICLE CANVAS ──────────────────────────────────────────── */
        #particleCanvas {
            position: fixed;
            inset: 0;
            z-index: 0;
            pointer-events: none;
            opacity: 0.5;
        }

        .glow-text {
            animation: fontLightPulse 3s infinite ease-in-out;

            /* ── 4. LOADER SCREEN ───────────────────────────────────────────── */
            #loader {
                position: fixed;
                inset: 0;
                z-index: 9999;
                background: var(--bg-deepest);
                display: flex;
                align-items: center;
                justify-content: center;
                transition: opacity 0.5s ease, visibility 0.5s ease;
            }

            #loader.hidden {
                opacity: 0;
                visibility: hidden;
                pointer-events: none;
            }

            /* 4. HEADER & MODERN FLOATING NAVBAR */
            .header {
                position: sticky;
                top: 0;
                background: rgba(11, 15, 25, 0.85);
                backdrop-filter: blur(16px);
                -webkit-backdrop-filter: blur(16px);
                border-bottom: 1px solid rgba(148, 163, 184, 0.12);
                padding: 14px 0;
                z-index: 1000;
                transition: all var(--transition-fast);

                .loader-inner {
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    gap: 20px;
                }

                .header.scrolled {
                    padding: 10px 0;
                    background: rgba(7, 10, 18, 0.95);
                    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.6);

                    .loader-logo {
                        width: 72px;
                        height: 72px;
                        border-radius: 20px;
                        background: linear-gradient(135deg, var(--blue-900), var(--blue-700));
                        border: 1px solid var(--border-blue);
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        font-size: 30px;
                        color: var(--cyan);
                        box-shadow: 0 0 40px var(--cyan-glow);
                        animation: loaderPulse 1.5s infinite;
                    }

                    .navbar {
                        display: flex;
                        justify-content: space-between;
                        align-items: center;
                        gap: 20px;

                        @keyframes loaderPulse {

                            0%,
                            100% {
                                box-shadow: 0 0 20px var(--cyan-glow);
                            }

                            50% {
                                box-shadow: 0 0 50px var(--cyan-glow), 0 0 80px rgba(0, 212, 255, 0.2);
                            }
                        }

                        /* Logo */
                        .logo {
                            display: flex;
                            align-items: center;
                            gap: 12px;
                            text-decoration: none;
                            color: var(--color-white);

                            .loader-bar {
                                width: 200px;
                                height: 3px;
                                background: rgba(255, 255, 255, 0.08);
                                border-radius: 999px;
                                overflow: hidden;
                            }

                            .logo-icon {
                                width: 44px;
                                height: 44px;
                                background: linear-gradient(135deg, var(--color-navy-main), var(--color-blue-accent));
                                border: 1px solid rgba(56, 189, 248, 0.4);
                                border-radius: 12px;
                                display: flex;
                                align-items: center;
                                justify-content: center;
                                font-size: 20px;
                                color: var(--color-cyan-glow);
                                box-shadow: 0 0 15px rgba(56, 189, 248, 0.3);
                                transition: all var(--transition-smooth);

                                .loader-fill {
                                    height: 100%;
                                    width: 0%;
                                    background: linear-gradient(90deg, var(--blue-700), var(--cyan));
                                    border-radius: 999px;
                                    animation: loaderFill 1.8s var(--ease) forwards;
                                }

                                .logo:hover .logo-icon {
                                    transform: rotate(10deg) scale(1.08);
                                    box-shadow: 0 0 25px rgba(56, 189, 248, 0.7);

                                    @keyframes loaderFill {
                                        to {
                                            width: 100%;
                                        }
                                    }

                                    .loader-text {
                                        font-size: 13px;
                                        color: var(--text-muted);
                                        letter-spacing: 1px;
                                    }

                                    .logo-text {
                                        font-size: 20px;
                                        font-weight: 800;
                                        letter-spacing: -0.5px;
                                        display: flex;
                                        flex-direction: column;

                                        /* ── 5. CONTAINER ──────────────────────────────────────────────── */
                                        .container {
                                            width: 92%;
                                            max-width: 1200px;
                                            margin: 0 auto;
                                            position: relative;
                                            z-index: 1;
                                        }

                                        .logo-sub {
                                            font-size: 11px;
                                            font-weight: 500;
                                            color: var(--color-gray-muted);
                                            letter-spacing: 1px;
                                            text-transform: uppercase;
                                            margin-top: -3px;

                                            /* ── 6. HEADER / NAVBAR ──────────────────────────────────────── */
                                            #mainHeader {
                                                position: sticky;
                                                top: 0;
                                                z-index: 500;
                                                background: rgba(6, 13, 26, 0.75);
                                                backdrop-filter: blur(20px);
                                                -webkit-backdrop-filter: blur(20px);
                                                border-bottom: 1px solid var(--border);
                                                transition: all var(--t-fast);
                                            }

                                            /* Nav Links - Halaman Interaktif */
                                            .nav-container {
                                                display: flex;
                                                align-items: center;

                                                #mainHeader.scrolled {
                                                    background: rgba(3, 7, 17, 0.95);
                                                    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6);
                                                }

                                                .nav-links {
                                                    display: flex;
                                                    list-style: none;
                                                    gap: 8px;
                                                    background: rgba(30, 41, 59, 0.6);
                                                    padding: 6px;
                                                    border-radius: 50px;
                                                    border: 1px solid rgba(148, 163, 184, 0.15);

                                                    .nav-wrap {
                                                        display: flex;
                                                        align-items: center;
                                                        justify-content: space-between;
                                                        gap: 16px;
                                                        padding: 14px 0;
                                                    }

                                                    .nav-link {
                                                        background: transparent;
                                                        border: none;
                                                        color: var(--color-gray-muted);
                                                        padding: 8px 18px;
                                                        border-radius: 30px;
                                                        font-size: 14px;
                                                        font-weight: 600;
                                                        display: flex;
                                                        align-items: center;
                                                        gap: 8px;
                                                        transition: all var(--transition-smooth);

                                                        /* Brand */
                                                        .brand {
                                                            display: flex;
                                                            align-items: center;
                                                            gap: 12px;
                                                            cursor: pointer;
                                                            text-decoration: none;
                                                            flex-shrink: 0;
                                                        }

                                                        .nav-link i {
                                                            font-size: 13px;
                                                            transition: transform var(--transition-fast);

                                                            .brand-icon {
                                                                width: 44px;
                                                                height: 44px;
                                                                border-radius: 12px;
                                                                background: linear-gradient(135deg, var(--blue-900), var(--blue-700));
                                                                border: 1px solid var(--border-blue);
                                                                display: flex;
                                                                align-items: center;
                                                                justify-content: center;
                                                                font-size: 20px;
                                                                color: var(--cyan);
                                                                box-shadow: 0 0 20px rgba(0, 212, 255, 0.25);
                                                                transition: all var(--t-med);
                                                            }

                                                            .nav-link:hover {
                                                                color: var(--color-white);
                                                                background: rgba(255, 255, 255, 0.05);

                                                                .brand:hover .brand-icon {
                                                                    transform: scale(1.08) rotate(8deg);
                                                                    box-shadow: 0 0 35px var(--cyan-glow);
                                                                }

                                                                .brand-name {
                                                                    display: block;
                                                                    font-family: var(--font-head);
                                                                    font-size: 18px;
                                                                    font-weight: 700;
                                                                    color: var(--text-white);
                                                                }

                                                                .nav-link:hover i {
                                                                    transform: translateY(-1px);

                                                                    .brand-name em {
                                                                        color: var(--cyan);
                                                                        font-style: normal;
                                                                    }

                                                                    .brand-tagline {
                                                                        display: block;
                                                                        font-size: 11px;
                                                                        color: var(--text-muted);
                                                                        letter-spacing: 0.8px;
                                                                        text-transform: uppercase;
                                                                    }

                                                                    /* Status Nav Aktif dengan Pencahayaan */
                                                                    .nav-link.active {
                                                                        background: linear-gradient(135deg, var(--color-navy-main), var(--color-navy-light));
                                                                        color: var(--color-cyan-glow);
                                                                        border: 1px solid rgba(56, 189, 248, 0.4);
                                                                        box-shadow: 0 0 20px rgba(37, 99, 235, 0.5), inset 0 0 10px rgba(56, 189, 248, 0.2);
                                                                        text-shadow: 0 0 10px rgba(56, 189, 248, 0.8);

                                                                        /* Desktop Nav */
                                                                        .desktop-nav {
                                                                            display: flex;
                                                                            align-items: center;
                                                                            gap: 4px;
                                                                            background: rgba(255, 255, 255, 0.03);
                                                                            border: 1px solid var(--border);
                                                                            padding: 5px;
                                                                            border-radius: 999px;
                                                                        }

                                                                        /* Header Actions */
                                                                        .header-actions {
                                                                            display: flex;
                                                                            align-items: center;
                                                                            gap: 15px;

                                                                            .nav-item {
                                                                                font-size: 13.5px;
                                                                                font-weight: 600;
                                                                                color: var(--text-secondary);
                                                                                padding: 8px 16px;
                                                                                border-radius: 999px;
                                                                                display: flex;
                                                                                align-items: center;
                                                                                gap: 7px;
                                                                                cursor: pointer;
                                                                                transition: all var(--t-fast);
                                                                            }

                                                                            .badge-status {
                                                                                display: flex;
                                                                                align-items: center;
                                                                                gap: 8px;
                                                                                background: rgba(15, 23, 42, 0.7);
                                                                                border: 1px solid rgba(148, 163, 184, 0.15);
                                                                                padding: 6px 14px;
                                                                                border-radius: 30px;
                                                                                font-size: 12px;
                                                                                color: var(--color-gray-light);

                                                                                .nav-item i {
                                                                                    font-size: 12px;
                                                                                }

                                                                                .nav-item:hover {
                                                                                    color: var(--text-white);
                                                                                    background: rgba(255, 255, 255, 0.05);
                                                                                }

                                                                                .nav-item.active {
                                                                                    background: linear-gradient(135deg, var(--blue-900), var(--blue-700));
                                                                                    color: var(--cyan);
                                                                                    border: 1px solid var(--border-blue);
                                                                                    box-shadow: 0 0 20px rgba(26, 86, 219, 0.4);
                                                                                }

                                                                                .pulse-dot {
                                                                                    width: 8px;
                                                                                    height: 8px;
                                                                                    background-color: #22c55e;
                                                                                    border-radius: 50%;
                                                                                    box-shadow: 0 0 10px #22c55e;
                                                                                    animation: dotPulse 1.8s infinite;
                                                                                }

                                                                                /* Header Right */
                                                                                .header-right {
                                                                                    display: flex;
                                                                                    align-items: center;
                                                                                    gap: 12px;
                                                                                    flex-shrink: 0;
                                                                                }

                                                                                @keyframes dotPulse {
                                                                                    0% {
                                                                                        transform: scale(0.95);
                                                                                        box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.7);
                                                                                    }

                                                                                    70% {
                                                                                        transform: scale(1.1);
                                                                                        box-shadow: 0 0 0 8px rgba(34, 197, 94, 0);
                                                                                    }

                                                                                    100% {
                                                                                        transform: scale(0.95);
                                                                                        box-shadow: 0 0 0 0 rgba(34, 197, 94, 0);
                                                                                    }

                                                                                    .live-badge {
                                                                                        display: flex;
                                                                                        align-items: center;
                                                                                        gap: 7px;
                                                                                        font-size: 12px;
                                                                                        color: var(--text-secondary);
                                                                                        background: rgba(255, 255, 255, 0.03);
                                                                                        border: 1px solid var(--border);
                                                                                        padding: 5px 12px;
                                                                                        border-radius: 999px;
                                                                                    }

                                                                                    .btn-nav-cta {
                                                                                        background: linear-gradient(135deg, #16a34a, #22c55e);
                                                                                        color: white;
                                                                                        text-decoration: none;
                                                                                        padding: 8px 18px;
                                                                                        border-radius: 30px;
                                                                                        font-size: 13px;
                                                                                        font-weight: 700;
                                                                                        display: flex;
                                                                                        align-items: center;
                                                                                        gap: 8px;
                                                                                        box-shadow: 0 4px 15px rgba(34, 197, 94, 0.35);
                                                                                        transition: all var(--transition-smooth);

                                                                                        .live-dot {
                                                                                            width: 7px;
                                                                                            height: 7px;
                                                                                            border-radius: 50%;
                                                                                            background: var(--green);
                                                                                            box-shadow: 0 0 8px var(--green);
                                                                                            animation: livePulse 2s infinite;
                                                                                        }

                                                                                        .btn-nav-cta:hover {
                                                                                            transform: translateY(-2px);
                                                                                            box-shadow: 0 6px 20px rgba(34, 197, 94, 0.55), 0 0 15px rgba(34, 197, 94, 0.4);

                                                                                            @keyframes livePulse {

                                                                                                0%,
                                                                                                100% {
                                                                                                    box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.7);
                                                                                                }

                                                                                                50% {
                                                                                                    box-shadow: 0 0 0 7px rgba(34, 197, 94, 0);
                                                                                                }
                                                                                            }

                                                                                            .mobile-toggle {
                                                                                                display: none;
                                                                                                background: transparent;
                                                                                                border: 1px solid rgba(148, 163, 184, 0.2);
                                                                                                color: var(--color-white);
                                                                                                font-size: 20px;
                                                                                                width: 42px;
                                                                                                height: 42px;
                                                                                                border-radius: 10px;
                                                                                                cursor: pointer;

                                                                                                .btn-header-cta {
                                                                                                    background: var(--green);
                                                                                                    color: #fff;
                                                                                                    font-size: 13px;
                                                                                                    font-weight: 700;
                                                                                                    padding: 9px 18px;
                                                                                                    border-radius: 999px;
                                                                                                    display: flex;
                                                                                                    align-items: center;
                                                                                                    gap: 8px;
                                                                                                    box-shadow: 0 4px 20px rgba(34, 197, 94, 0.35);
                                                                                                    transition: all var(--t-fast);
                                                                                                }

                                                                                                /* 5. STEP PROGRESS TRACKER (Indikator Halaman 1-4) */
                                                                                                .page-tracker-container {
                                                                                                    background: rgba(15, 23, 42, 0.4);
                                                                                                    border-bottom: 1px solid rgba(148, 163, 184, 0.08);
                                                                                                    padding: 10px 0;
                                                                                                    font-size: 13px;
                                                                                                    position: relative;
                                                                                                    z-index: 10;

                                                                                                    .btn-header-cta:hover {
                                                                                                        transform: translateY(-2px);
                                                                                                        box-shadow: 0 8px 28px rgba(34, 197, 94, 0.55);
                                                                                                    }

                                                                                                    .tracker-flex {
                                                                                                        display: flex;
                                                                                                        justify-content: space-between;
                                                                                                        align-items: center;

                                                                                                        /* Hamburger */
                                                                                                        .hamburger {
                                                                                                            display: none;
                                                                                                            flex-direction: column;
                                                                                                            gap: 5px;
                                                                                                            width: 40px;
                                                                                                            height: 40px;
                                                                                                            border-radius: 10px;
                                                                                                            background: rgba(255, 255, 255, 0.05);
                                                                                                            border: 1px solid var(--border);
                                                                                                            align-items: center;
                                                                                                            justify-content: center;
                                                                                                            transition: all var(--t-fast);
                                                                                                        }

                                                                                                        .tracker-info {
                                                                                                            color: var(--color-gray-muted);

                                                                                                            .hamburger span {
                                                                                                                display: block;
                                                                                                                width: 20px;
                                                                                                                height: 2px;
                                                                                                                background: var(--text-primary);
                                                                                                                border-radius: 2px;
                                                                                                                transition: all var(--t-fast);
                                                                                                            }

                                                                                                            .hamburger.open span:nth-child(1) {
                                                                                                                transform: translateY(7px) rotate(45deg);
                                                                                                            }

                                                                                                            .hamburger.open span:nth-child(2) {
                                                                                                                opacity: 0;
                                                                                                            }

                                                                                                            .hamburger.open span:nth-child(3) {
                                                                                                                transform: translateY(-7px) rotate(-45deg);
                                                                                                            }

                                                                                                            .tracker-info strong {
                                                                                                                color: var(--color-cyan-glow);
                                                                                                                font-weight: 600;

                                                                                                                /* Mobile Nav */
                                                                                                                .mobile-nav {
                                                                                                                    position: fixed;
                                                                                                                    top: 0;
                                                                                                                    left: 0;
                                                                                                                    width: 100%;
                                                                                                                    height: 100vh;
                                                                                                                    background: rgba(3, 7, 17, 0.98);
                                                                                                                    backdrop-filter: blur(24px);
                                                                                                                    z-index: 490;
                                                                                                                    transform: translateX(-100%);
                                                                                                                    transition: transform var(--t-med);
                                                                                                                }

                                                                                                                .tracker-steps {
                                                                                                                    display: flex;
                                                                                                                    align-items: center;
                                                                                                                    gap: 6px;

                                                                                                                    .mobile-nav.open {
                                                                                                                        transform: translateX(0);
                                                                                                                    }

                                                                                                                    .mobile-nav-inner {
                                                                                                                        display: flex;
                                                                                                                        flex-direction: column;
                                                                                                                        justify-content: center;
                                                                                                                        gap: 8px;
                                                                                                                        padding: 80px 10% 40px;
                                                                                                                        height: 100%;
                                                                                                                    }

                                                                                                                    .step-dot {
                                                                                                                        width: 28px;
                                                                                                                        height: 28px;
                                                                                                                        border-radius: 50%;
                                                                                                                        background: var(--color-gray-dark);
                                                                                                                        border: 1px solid rgba(148, 163, 184, 0.2);
                                                                                                                        color: var(--color-gray-muted);
                                                                                                                        font-size: 12px;
                                                                                                                        font-weight: 700;
                                                                                                                        cursor: pointer;
                                                                                                                        display: flex;
                                                                                                                        align-items: center;
                                                                                                                        justify-content: center;
                                                                                                                        transition: all var(--transition-smooth);

                                                                                                                        .mnav-item {
                                                                                                                            display: flex;
                                                                                                                            align-items: center;
                                                                                                                            gap: 16px;
                                                                                                                            font-family: var(--font-head);
                                                                                                                            font-size: 1.6rem;
                                                                                                                            font-weight: 700;
                                                                                                                            color: rgba(255, 255, 255, 0.4);
                                                                                                                            padding: 14px 0;
                                                                                                                            border-bottom: 1px solid rgba(255, 255, 255, 0.05);
                                                                                                                            cursor: pointer;
                                                                                                                            transition: all var(--t-fast);
                                                                                                                        }

                                                                                                                        .step-dot:hover {
                                                                                                                            color: var(--color-white);
                                                                                                                            border-color: var(--color-cyan-glow);
                                                                                                                            box-shadow: 0 0 10px rgba(56, 189, 248, 0.4);

                                                                                                                            .mnav-item:hover,
                                                                                                                            .mnav-item.active {
                                                                                                                                color: var(--text-white);
                                                                                                                            }

                                                                                                                            .mnav-item.active {
                                                                                                                                color: var(--cyan);
                                                                                                                            }

                                                                                                                            .mnav-num {
                                                                                                                                font-size: 12px;
                                                                                                                                color: var(--text-muted);
                                                                                                                                font-family: var(--font-body);
                                                                                                                            }

                                                                                                                            .btn-mobile-wa {
                                                                                                                                margin-top: 28px;
                                                                                                                                background: var(--green);
                                                                                                                                color: #fff;
                                                                                                                                font-weight: 700;
                                                                                                                                padding: 14px 24px;
                                                                                                                                border-radius: 12px;
                                                                                                                                display: flex;
                                                                                                                                align-items: center;
                                                                                                                                justify-content: center;
                                                                                                                                gap: 10px;
                                                                                                                                font-size: 16px;
                                                                                                                            }

                                                                                                                            .step-dot.active {
                                                                                                                                background: linear-gradient(135deg, var(--color-navy-main), var(--color-blue-accent));
                                                                                                                                color: var(--color-white);
                                                                                                                                border-color: var(--color-cyan-glow);
                                                                                                                                box-shadow: 0 0 15px rgba(56, 189, 248, 0.7);
                                                                                                                                transform: scale(1.1);

                                                                                                                                /* ── 7. PAGE INDICATOR (RIGHT SIDE DOTS) ──────────────────────── */
                                                                                                                                .page-indicator {
                                                                                                                                    position: fixed;
                                                                                                                                    right: 24px;
                                                                                                                                    top: 50%;
                                                                                                                                    transform: translateY(-50%);
                                                                                                                                    z-index: 200;
                                                                                                                                    display: flex;
                                                                                                                                    flex-direction: column;
                                                                                                                                    gap: 12px;
                                                                                                                                }

                                                                                                                                .step-line {
                                                                                                                                    width: 20px;
                                                                                                                                    height: 2px;
                                                                                                                                    background: rgba(148, 163, 184, 0.2);

                                                                                                                                    .pi-dot {
                                                                                                                                        width: 8px;
                                                                                                                                        height: 8px;
                                                                                                                                        border-radius: 50%;
                                                                                                                                        background: rgba(255, 255, 255, 0.15);
                                                                                                                                        border: 1px solid rgba(255, 255, 255, 0.1);
                                                                                                                                        cursor: pointer;
                                                                                                                                        transition: all var(--t-fast);
                                                                                                                                        position: relative;
                                                                                                                                    }

                                                                                                                                    /* 6. MAIN MULTI-PAGE WRAPPER & ANIMASI HALAMAN */
                                                                                                                                    .pages-wrapper {
                                                                                                                                        position: relative;
                                                                                                                                        min-height: 80vh;
                                                                                                                                        padding: 40px 0 60px;
                                                                                                                                        z-index: 1;

                                                                                                                                        .pi-dot::after {
                                                                                                                                            content: attr(title);
                                                                                                                                            position: absolute;
                                                                                                                                            right: 20px;
                                                                                                                                            top: 50%;
                                                                                                                                            transform: translateY(-50%);
                                                                                                                                            font-size: 11px;
                                                                                                                                            color: var(--text-white);
                                                                                                                                            white-space: nowrap;
                                                                                                                                            background: rgba(6, 13, 26, 0.9);
                                                                                                                                            padding: 4px 10px;
                                                                                                                                            border-radius: 6px;
                                                                                                                                            opacity: 0;
                                                                                                                                            pointer-events: none;
                                                                                                                                            transition: opacity var(--t-fast);
                                                                                                                                        }

                                                                                                                                        /* Konsep Halaman Tersendiri (Setiap section adalah satu halaman utuh) */
                                                                                                                                        .page-view {
                                                                                                                                            display: none;
                                                                                                                                            opacity: 0;
                                                                                                                                            transform: translateY(20px);
                                                                                                                                            transition: opacity 0.4s ease, transform 0.4s ease;

                                                                                                                                            .pi-dot:hover::after {
                                                                                                                                                opacity: 1;
                                                                                                                                            }

                                                                                                                                            .pi-dot:hover {
                                                                                                                                                background: rgba(0, 212, 255, 0.4);
                                                                                                                                            }

                                                                                                                                            .pi-dot.active {
                                                                                                                                                background: var(--cyan);
                                                                                                                                                box-shadow: 0 0 12px var(--cyan-glow);
                                                                                                                                                transform: scale(1.4);
                                                                                                                                            }

                                                                                                                                            .page-view.active-page {
                                                                                                                                                display: block;
                                                                                                                                                opacity: 1;
                                                                                                                                                transform: translateY(0);
                                                                                                                                                animation: pageReveal 0.45s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                                                                                                                                            }

                                                                                                                                            /* ── 8. PAGES SYSTEM ──────────────────────────────────────────── */
                                                                                                                                            .pages-root {
                                                                                                                                                position: relative;
                                                                                                                                                z-index: 1;
                                                                                                                                            }

                                                                                                                                            @keyframes pageReveal {
                                                                                                                                                0% {
                                                                                                                                                    opacity: 0;
                                                                                                                                                    transform: translateY(18px) scale(0.99);
                                                                                                                                                }

                                                                                                                                                100% {
                                                                                                                                                    opacity: 1;
                                                                                                                                                    transform: translateY(0) scale(1);
                                                                                                                                                }

                                                                                                                                                .page {
                                                                                                                                                    display: none;
                                                                                                                                                    opacity: 0;
                                                                                                                                                    padding: 80px 0 60px;
                                                                                                                                                    min-height: 100vh;
                                                                                                                                                    animation: pageIn 0.5s var(--ease) forwards;
                                                                                                                                                }

                                                                                                                                                .page.active-page {
                                                                                                                                                    display: block;
                                                                                                                                                }

                                                                                                                                                .page.page-enter {
                                                                                                                                                    animation: pageIn 0.5s var(--ease) forwards;
                                                                                                                                                }

                                                                                                                                                /* 7. HERO SECTION (HALAMAN HOME) */
                                                                                                                                                .hero-grid {
                                                                                                                                                    display: grid;
                                                                                                                                                    grid-template-columns: 1.15fr 0.85fr;
                                                                                                                                                    gap: 40px;
                                                                                                                                                    align-items: center;
                                                                                                                                                    padding: 20px 0 60px;

                                                                                                                                                    @keyframes pageIn {
                                                                                                                                                        from {
                                                                                                                                                            opacity: 0;
                                                                                                                                                            transform: translateY(16px);
                                                                                                                                                        }

                                                                                                                                                        to {
                                                                                                                                                            opacity: 1;
                                                                                                                                                            transform: translateY(0);
                                                                                                                                                        }
                                                                                                                                                    }

                                                                                                                                                    .badge-tag {
                                                                                                                                                        display: inline-flex;
                                                                                                                                                        align-items: center;
                                                                                                                                                        gap: 8px;
                                                                                                                                                        background: rgba(30, 58, 138, 0.35);
                                                                                                                                                        border: 1px solid rgba(56, 189, 248, 0.3);
                                                                                                                                                        padding: 6px 16px;
                                                                                                                                                        border-radius: 30px;
                                                                                                                                                        font-size: 13px;
                                                                                                                                                        font-weight: 600;
                                                                                                                                                        color: var(--color-cyan-glow);
                                                                                                                                                        margin-bottom: 24px;
                                                                                                                                                        box-shadow: 0 0 15px rgba(30, 58, 138, 0.4);
                                                                                                                                                    }

                                                                                                                                                    /* ── 9. SECTION HEADERS ───────────────────────────────────────── */
                                                                                                                                                    .section-header {
                                                                                                                                                        text-align: center;
                                                                                                                                                        margin-bottom: 3.5rem;
                                                                                                                                                    }

                                                                                                                                                    .section-header.left {
                                                                                                                                                        text-align: left;
                                                                                                                                                    }

                                                                                                                                                    .hero-title {
                                                                                                                                                        font-size: 2.85rem;
                                                                                                                                                        font-weight: 800;
                                                                                                                                                        letter-spacing: -1px;
                                                                                                                                                        line-height: 1.2;
                                                                                                                                                        margin-bottom: 20px;

                                                                                                                                                        .sh-eyebrow {
                                                                                                                                                            display: inline-flex;
                                                                                                                                                            align-items: center;
                                                                                                                                                            font-size: 12px;
                                                                                                                                                            font-weight: 700;
                                                                                                                                                            letter-spacing: 1.5px;
                                                                                                                                                            text-transform: uppercase;
                                                                                                                                                            color: var(--cyan);
                                                                                                                                                            background: var(--cyan-dim);
                                                                                                                                                            border: 1px solid var(--border-blue);
                                                                                                                                                            padding: 5px 16px;
                                                                                                                                                            border-radius: 999px;
                                                                                                                                                            margin-bottom: 14px;
                                                                                                                                                        }

                                                                                                                                                        .hero-description {
                                                                                                                                                            font-size: 1.1rem;
                                                                                                                                                            color: var(--color-gray-muted);
                                                                                                                                                            margin-bottom: 35px;
                                                                                                                                                            max-width: 580px;

                                                                                                                                                            .sh-title {
                                                                                                                                                                font-family: var(--font-head);
                                                                                                                                                                font-size: clamp(1.75rem, 4vw, 2.8rem);
                                                                                                                                                                font-weight: 800;
                                                                                                                                                                color: var(--text-white);
                                                                                                                                                                line-height: 1.2;
                                                                                                                                                                letter-spacing: -0.5px;
                                                                                                                                                                margin-bottom: 14px;
                                                                                                                                                            }

                                                                                                                                                            .hero-description strong {
                                                                                                                                                                color: var(--color-white);

                                                                                                                                                                .sh-desc {
                                                                                                                                                                    font-size: 1.05rem;
                                                                                                                                                                    color: var(--text-secondary);
                                                                                                                                                                    max-width: 640px;
                                                                                                                                                                    margin: 0 auto;
                                                                                                                                                                    line-height: 1.7;
                                                                                                                                                                }

                                                                                                                                                                .hero-buttons {
                                                                                                                                                                    display: flex;
                                                                                                                                                                    gap: 16px;
                                                                                                                                                                    flex-wrap: wrap;
                                                                                                                                                                    margin-bottom: 45px;

                                                                                                                                                                    /* Gradient Text */
                                                                                                                                                                    .gradient-text {
                                                                                                                                                                        background: linear-gradient(135deg, var(--cyan) 0%, var(--blue-500) 50%, var(--purple) 100%);
                                                                                                                                                                        -webkit-background-clip: text;
                                                                                                                                                                        -webkit-text-fill-color: transparent;
                                                                                                                                                                        background-clip: text;
                                                                                                                                                                    }

                                                                                                                                                                    /* Tombol Desain Glowing */
                                                                                                                                                                    .glow-btn {
                                                                                                                                                                        position: relative;
                                                                                                                                                                        overflow: hidden;
                                                                                                                                                                        transition: all var(--transition-smooth);

                                                                                                                                                                        /* ── 10. BUTTONS ───────────────────────────────────────────────── */
                                                                                                                                                                        .btn-primary {
                                                                                                                                                                            display: inline-flex;
                                                                                                                                                                            align-items: center;
                                                                                                                                                                            gap: 10px;
                                                                                                                                                                            background: linear-gradient(135deg, var(--blue-800), var(--blue-700));
                                                                                                                                                                            color: var(--text-white);
                                                                                                                                                                            font-size: 15px;
                                                                                                                                                                            font-weight: 700;
                                                                                                                                                                            padding: 14px 28px;
                                                                                                                                                                            border-radius: 12px;
                                                                                                                                                                            border: 1px solid var(--border-blue);
                                                                                                                                                                            box-shadow: var(--shadow-btn);
                                                                                                                                                                            transition: all var(--t-med);
                                                                                                                                                                            cursor: pointer;
                                                                                                                                                                            position: relative;
                                                                                                                                                                            overflow: hidden;
                                                                                                                                                                        }

                                                                                                                                                                        .glow-btn::before {
                                                                                                                                                                            content: '';
                                                                                                                                                                            position: absolute;
                                                                                                                                                                            top: 0;
                                                                                                                                                                            left: -100%;
                                                                                                                                                                            width: 100%;
                                                                                                                                                                            height: 100%;
                                                                                                                                                                            background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.25), transparent);
                                                                                                                                                                            transition: 0.6s;

                                                                                                                                                                            .btn-primary::before {
                                                                                                                                                                                content: '';
                                                                                                                                                                                position: absolute;
                                                                                                                                                                                inset: 0;
                                                                                                                                                                                background: linear-gradient(135deg, transparent, rgba(255, 255, 255, 0.12), transparent);
                                                                                                                                                                                transform: translateX(-100%);
                                                                                                                                                                                transition: transform 0.6s;
                                                                                                                                                                            }

                                                                                                                                                                            .glow-btn:hover::before {
                                                                                                                                                                                left: 100%;

                                                                                                                                                                                .btn-primary:hover::before {
                                                                                                                                                                                    transform: translateX(100%);
                                                                                                                                                                                }

                                                                                                                                                                                .btn-primary:hover {
                                                                                                                                                                                    transform: translateY(-3px);
                                                                                                                                                                                    box-shadow: 0 12px 40px rgba(26, 86, 219, 0.6), 0 0 25px var(--cyan-glow);
                                                                                                                                                                                    border-color: var(--border-hover);
                                                                                                                                                                                }

                                                                                                                                                                                .btn-primary {
                                                                                                                                                                                    background: linear-gradient(135deg, var(--color-navy-main), var(--color-blue-accent));
                                                                                                                                                                                    color: var(--color-white);
                                                                                                                                                                                    border: 1px solid rgba(56, 189, 248, 0.5);
                                                                                                                                                                                    padding: 14px 28px;
                                                                                                                                                                                    border-radius: 12px;
                                                                                                                                                                                    font-size: 15px;
                                                                                                                                                                                    font-weight: 700;
                                                                                                                                                                                    display: inline-flex;
                                                                                                                                                                                    align-items: center;
                                                                                                                                                                                    gap: 10px;
                                                                                                                                                                                    cursor: pointer;
                                                                                                                                                                                    box-shadow: 0 4px 20px rgba(37, 99, 235, 0.4), inset 0 0 10px rgba(56, 189, 248, 0.2);

                                                                                                                                                                                    .btn-ghost {
                                                                                                                                                                                        display: inline-flex;
                                                                                                                                                                                        align-items: center;
                                                                                                                                                                                        gap: 10px;
                                                                                                                                                                                        background: rgba(255, 255, 255, 0.04);
                                                                                                                                                                                        color: var(--text-white);
                                                                                                                                                                                        font-size: 15px;
                                                                                                                                                                                        font-weight: 600;
                                                                                                                                                                                        padding: 13px 26px;
                                                                                                                                                                                        border-radius: 12px;
                                                                                                                                                                                        border: 1px solid var(--border);
                                                                                                                                                                                        transition: all var(--t-fast);
                                                                                                                                                                                        cursor: pointer;
                                                                                                                                                                                    }

                                                                                                                                                                                    .btn-primary:hover {
                                                                                                                                                                                        transform: translateY(-3px);
                                                                                                                                                                                        box-shadow: 0 8px 30px rgba(37, 99, 235, 0.6), 0 0 20px rgba(56, 189, 248, 0.6);

                                                                                                                                                                                        .btn-ghost:hover {
                                                                                                                                                                                            background: rgba(255, 255, 255, 0.08);
                                                                                                                                                                                            border-color: var(--cyan);
                                                                                                                                                                                            color: var(--cyan);
                                                                                                                                                                                            transform: translateY(-2px);
                                                                                                                                                                                        }

                                                                                                                                                                                        .btn-secondary {
                                                                                                                                                                                            background: rgba(30, 41, 59, 0.6);
                                                                                                                                                                                            color: var(--color-white);
                                                                                                                                                                                            border: 1px solid rgba(148, 163, 184, 0.25);
                                                                                                                                                                                            padding: 14px 26px;
                                                                                                                                                                                            border-radius: 12px;
                                                                                                                                                                                            font-size: 15px;
                                                                                                                                                                                            font-weight: 600;
                                                                                                                                                                                            text-decoration: none;
                                                                                                                                                                                            display: inline-flex;
                                                                                                                                                                                            align-items: center;
                                                                                                                                                                                            gap: 10px;
                                                                                                                                                                                            cursor: pointer;
                                                                                                                                                                                        }

                                                                                                                                                                                        /* ── 11. HERO (PAGE 1) ──────────────────────────────────────────── */
                                                                                                                                                                                        .hero-wrap {
                                                                                                                                                                                            padding: 40px 0 20px;
                                                                                                                                                                                        }

                                                                                                                                                                                        .btn-secondary:hover {
                                                                                                                                                                                            background: rgba(51, 65, 85, 0.8);
                                                                                                                                                                                            border-color: var(--color-cyan-glow);
                                                                                                                                                                                            color: var(--color-cyan-glow);
                                                                                                                                                                                            transform: translateY(-3px);
                                                                                                                                                                                            box-shadow: 0 0 20px rgba(56, 189, 248, 0.25);

                                                                                                                                                                                            .hero-grid {
                                                                                                                                                                                                display: grid;
                                                                                                                                                                                                grid-template-columns: 1.1fr 0.9fr;
                                                                                                                                                                                                gap: 60px;
                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                padding-bottom: 60px;
                                                                                                                                                                                            }

                                                                                                                                                                                            /* Hero Stats */
                                                                                                                                                                                            .hero-stats {
                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                gap: 25px;
                                                                                                                                                                                                padding-top: 25px;
                                                                                                                                                                                                border-top: 1px solid rgba(148, 163, 184, 0.12);

                                                                                                                                                                                                .eyebrow-badge {
                                                                                                                                                                                                    display: inline-flex;
                                                                                                                                                                                                    align-items: center;
                                                                                                                                                                                                    gap: 10px;
                                                                                                                                                                                                    font-size: 13px;
                                                                                                                                                                                                    font-weight: 600;
                                                                                                                                                                                                    color: var(--cyan);
                                                                                                                                                                                                    background: var(--cyan-dim);
                                                                                                                                                                                                    border: 1px solid var(--border-blue);
                                                                                                                                                                                                    padding: 6px 16px;
                                                                                                                                                                                                    border-radius: 999px;
                                                                                                                                                                                                    margin-bottom: 28px;
                                                                                                                                                                                                }

                                                                                                                                                                                                .stat-item {
                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                    flex-direction: column;

                                                                                                                                                                                                    .badge-pulse {
                                                                                                                                                                                                        width: 7px;
                                                                                                                                                                                                        height: 7px;
                                                                                                                                                                                                        border-radius: 50%;
                                                                                                                                                                                                        background: var(--cyan);
                                                                                                                                                                                                        flex-shrink: 0;
                                                                                                                                                                                                        animation: livePulse 2s infinite;
                                                                                                                                                                                                    }

                                                                                                                                                                                                    .stat-number {
                                                                                                                                                                                                        font-size: 1.8rem;
                                                                                                                                                                                                        font-weight: 800;
                                                                                                                                                                                                        color: var(--color-white);
                                                                                                                                                                                                        line-height: 1;
                                                                                                                                                                                                        margin-bottom: 4px;

                                                                                                                                                                                                        .hero-headline {
                                                                                                                                                                                                            font-family: var(--font-head);
                                                                                                                                                                                                            font-size: clamp(2.2rem, 5vw, 3.8rem);
                                                                                                                                                                                                            font-weight: 800;
                                                                                                                                                                                                            color: var(--text-white);
                                                                                                                                                                                                            line-height: 1.15;
                                                                                                                                                                                                            letter-spacing: -1.5px;
                                                                                                                                                                                                            margin-bottom: 22px;
                                                                                                                                                                                                        }

                                                                                                                                                                                                        .stat-label {
                                                                                                                                                                                                            font-size: 12px;
                                                                                                                                                                                                            color: var(--color-gray-muted);

                                                                                                                                                                                                            .hero-sub {
                                                                                                                                                                                                                font-size: 1.1rem;
                                                                                                                                                                                                                color: var(--text-secondary);
                                                                                                                                                                                                                line-height: 1.75;
                                                                                                                                                                                                                max-width: 540px;
                                                                                                                                                                                                                margin-bottom: 36px;
                                                                                                                                                                                                            }

                                                                                                                                                                                                            .stat-divider {
                                                                                                                                                                                                                width: 1px;
                                                                                                                                                                                                                height: 35px;
                                                                                                                                                                                                                background: rgba(148, 163, 184, 0.15);
                                                                                                                                                                                                            }

                                                                                                                                                                                                            .hero-ctas {
                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                gap: 14px;
                                                                                                                                                                                                                flex-wrap: wrap;
                                                                                                                                                                                                                margin-bottom: 36px;
                                                                                                                                                                                                            }

                                                                                                                                                                                                            /* Hero Media & Image Box */
                                                                                                                                                                                                            .hero-media {
                                                                                                                                                                                                                position: relative;

                                                                                                                                                                                                                .trust-row {
                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                    align-items: center;
                                                                                                                                                                                                                    gap: 16px;
                                                                                                                                                                                                                    flex-wrap: wrap;
                                                                                                                                                                                                                    padding-top: 28px;
                                                                                                                                                                                                                    border-top: 1px solid var(--border);
                                                                                                                                                                                                                }

                                                                                                                                                                                                                .trust-item {
                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                    align-items: center;
                                                                                                                                                                                                                    gap: 8px;
                                                                                                                                                                                                                    font-size: 13px;
                                                                                                                                                                                                                    color: var(--text-secondary);
                                                                                                                                                                                                                }

                                                                                                                                                                                                                .trust-item i {
                                                                                                                                                                                                                    color: var(--cyan);
                                                                                                                                                                                                                    font-size: 14px;
                                                                                                                                                                                                                }

                                                                                                                                                                                                                .trust-sep {
                                                                                                                                                                                                                    color: var(--border);
                                                                                                                                                                                                                    font-size: 18px;
                                                                                                                                                                                                                }

                                                                                                                                                                                                                .glow-box {
                                                                                                                                                                                                                    position: relative;
                                                                                                                                                                                                                    border-radius: 20px;
                                                                                                                                                                                                                    background: var(--color-gray-dark);
                                                                                                                                                                                                                    padding: 10px;
                                                                                                                                                                                                                    border: 1px solid rgba(56, 189, 248, 0.25);
                                                                                                                                                                                                                    box-shadow: var(--glow-box);
                                                                                                                                                                                                                    overflow: hidden;

                                                                                                                                                                                                                    /* Hero Right Card */
                                                                                                                                                                                                                    .hero-card-wrap {
                                                                                                                                                                                                                        position: relative;
                                                                                                                                                                                                                    }

                                                                                                                                                                                                                    .hero-img-container {
                                                                                                                                                                                                                        border-radius: var(--r-xl);
                                                                                                                                                                                                                        overflow: hidden;
                                                                                                                                                                                                                        position: relative;
                                                                                                                                                                                                                        border: 1px solid var(--border-blue);
                                                                                                                                                                                                                        box-shadow: var(--shadow-card), 0 0 60px rgba(0, 212, 255, 0.15);
                                                                                                                                                                                                                    }

                                                                                                                                                                                                                    .glow-box::after {
                                                                                                                                                                                                                        content: '';
                                                                                                                                                                                                                        position: absolute;
                                                                                                                                                                                                                        inset: 0;
                                                                                                                                                                                                                        border-radius: 20px;
                                                                                                                                                                                                                        padding: 1px;
                                                                                                                                                                                                                        background: linear-gradient(135deg, rgba(56, 189, 248, 0.5), transparent, rgba(37, 99, 235, 0.4));
                                                                                                                                                                                                                        -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
                                                                                                                                                                                                                        -webkit-mask-composite: xor;
                                                                                                                                                                                                                        mask-composite: exclude;
                                                                                                                                                                                                                        pointer-events: none;

                                                                                                                                                                                                                        .hero-img {
                                                                                                                                                                                                                            width: 100%;
                                                                                                                                                                                                                            height: 460px;
                                                                                                                                                                                                                            object-fit: cover;
                                                                                                                                                                                                                            display: block;
                                                                                                                                                                                                                        }

                                                                                                                                                                                                                        .hero-img-overlay {
                                                                                                                                                                                                                            position: absolute;
                                                                                                                                                                                                                            inset: 0;
                                                                                                                                                                                                                            background: linear-gradient(to top, rgba(6, 13, 26, 0.6), transparent 50%);
                                                                                                                                                                                                                        }

                                                                                                                                                                                                                        .hero-img {
                                                                                                                                                                                                                            width: 100%;
                                                                                                                                                                                                                            height: 420px;
                                                                                                                                                                                                                            object-fit: cover;
                                                                                                                                                                                                                            border-radius: 16px;
                                                                                                                                                                                                                            display: block;
                                                                                                                                                                                                                            transition: transform 0.5s ease;

                                                                                                                                                                                                                            /* Floating Widgets */
                                                                                                                                                                                                                            .float-widget {
                                                                                                                                                                                                                                position: absolute;
                                                                                                                                                                                                                                background: rgba(6, 13, 26, 0.92);
                                                                                                                                                                                                                                backdrop-filter: blur(12px);
                                                                                                                                                                                                                                border: 1px solid var(--border-blue);
                                                                                                                                                                                                                                border-radius: 16px;
                                                                                                                                                                                                                                padding: 12px 18px;
                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                gap: 12px;
                                                                                                                                                                                                                                box-shadow: 0 12px 32px rgba(0, 0, 0, 0.6), 0 0 20px rgba(0, 212, 255, 0.15);
                                                                                                                                                                                                                                z-index: 2;
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                            .hero-media:hover .hero-img {
                                                                                                                                                                                                                                transform: scale(1.02);

                                                                                                                                                                                                                                .fw-top-left {
                                                                                                                                                                                                                                    top: 20px;
                                                                                                                                                                                                                                    left: -30px;
                                                                                                                                                                                                                                    animation: float1 5s ease-in-out infinite;
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                .fw-bottom-right {
                                                                                                                                                                                                                                    bottom: 30px;
                                                                                                                                                                                                                                    right: -25px;
                                                                                                                                                                                                                                    animation: float1 5s ease-in-out 1.5s infinite;
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                .fw-mid-left {
                                                                                                                                                                                                                                    top: 50%;
                                                                                                                                                                                                                                    left: -35px;
                                                                                                                                                                                                                                    transform: translateY(-50%);
                                                                                                                                                                                                                                    animation: float1 5s ease-in-out 3s infinite;
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                @keyframes float1 {

                                                                                                                                                                                                                                    0%,
                                                                                                                                                                                                                                    100% {
                                                                                                                                                                                                                                        transform: translateY(0);
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                    50% {
                                                                                                                                                                                                                                        transform: translateY(-8px);
                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                /* Floating Badges */
                                                                                                                                                                                                                                .floating-badge {
                                                                                                                                                                                                                                    position: absolute;
                                                                                                                                                                                                                                    background: rgba(15, 23, 42, 0.92);
                                                                                                                                                                                                                                    backdrop-filter: blur(12px);
                                                                                                                                                                                                                                    border: 1px solid rgba(56, 189, 248, 0.3);
                                                                                                                                                                                                                                    padding: 12px 18px;
                                                                                                                                                                                                                                    border-radius: 14px;
                                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                                    align-items: center;
                                                                                                                                                                                                                                    gap: 12px;
                                                                                                                                                                                                                                    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.6), 0 0 15px rgba(30, 58, 138, 0.4);
                                                                                                                                                                                                                                    z-index: 2;
                                                                                                                                                                                                                                    animation: floatAnim 4s ease-in-out infinite;

                                                                                                                                                                                                                                    .fw-mid-left {
                                                                                                                                                                                                                                        animation: float2 5s ease-in-out 3s infinite;
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                    @keyframes float2 {

                                                                                                                                                                                                                                        0%,
                                                                                                                                                                                                                                        100% {
                                                                                                                                                                                                                                            transform: translateY(-50%);
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        50% {
                                                                                                                                                                                                                                            transform: translateY(calc(-50% - 8px));
                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                    .floating-badge i {
                                                                                                                                                                                                                                        font-size: 22px;
                                                                                                                                                                                                                                        color: var(--color-cyan-glow);

                                                                                                                                                                                                                                        .fw-icon {
                                                                                                                                                                                                                                            width: 40px;
                                                                                                                                                                                                                                            height: 40px;
                                                                                                                                                                                                                                            border-radius: 10px;
                                                                                                                                                                                                                                            background: var(--cyan-dim);
                                                                                                                                                                                                                                            border: 1px solid var(--border-blue);
                                                                                                                                                                                                                                            display: flex;
                                                                                                                                                                                                                                            align-items: center;
                                                                                                                                                                                                                                            justify-content: center;
                                                                                                                                                                                                                                            font-size: 18px;
                                                                                                                                                                                                                                            color: var(--cyan);
                                                                                                                                                                                                                                            flex-shrink: 0;
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        .fw-icon.fw-green {
                                                                                                                                                                                                                                            background: var(--green-dim);
                                                                                                                                                                                                                                            color: var(--green);
                                                                                                                                                                                                                                            border-color: rgba(34, 197, 94, 0.3);
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        .fw-icon.fw-gold {
                                                                                                                                                                                                                                            background: var(--gold-dim);
                                                                                                                                                                                                                                            color: var(--gold);
                                                                                                                                                                                                                                            border-color: rgba(245, 158, 11, 0.3);
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        .fw-text span {
                                                                                                                                                                                                                                            display: block;
                                                                                                                                                                                                                                            font-size: 11px;
                                                                                                                                                                                                                                            color: var(--text-muted);
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        .fw-text strong {
                                                                                                                                                                                                                                            display: block;
                                                                                                                                                                                                                                            font-size: 13px;
                                                                                                                                                                                                                                            color: var(--text-white);
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        .floating-badge small {
                                                                                                                                                                                                                                            display: block;
                                                                                                                                                                                                                                            font-size: 11px;
                                                                                                                                                                                                                                            color: var(--color-gray-muted);

                                                                                                                                                                                                                                            /* Scroll Hint */
                                                                                                                                                                                                                                            .scroll-hint {
                                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                                flex-direction: column;
                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                gap: 10px;
                                                                                                                                                                                                                                                padding: 20px 0 40px;
                                                                                                                                                                                                                                                color: var(--text-muted);
                                                                                                                                                                                                                                                font-size: 12px;
                                                                                                                                                                                                                                                letter-spacing: 1px;
                                                                                                                                                                                                                                                text-transform: uppercase;
                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                            .floating-badge strong {
                                                                                                                                                                                                                                                font-size: 13px;
                                                                                                                                                                                                                                                color: var(--color-white);

                                                                                                                                                                                                                                                .scroll-line {
                                                                                                                                                                                                                                                    width: 1px;
                                                                                                                                                                                                                                                    height: 50px;
                                                                                                                                                                                                                                                    background: linear-gradient(to bottom, var(--cyan), transparent);
                                                                                                                                                                                                                                                    animation: scrollDrop 2s ease-in-out infinite;
                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                .badge-1 {
                                                                                                                                                                                                                                                    top: 25px;
                                                                                                                                                                                                                                                    left: -25px;
                                                                                                                                                                                                                                                    animation-delay: 0s;

                                                                                                                                                                                                                                                    @keyframes scrollDrop {
                                                                                                                                                                                                                                                        0% {
                                                                                                                                                                                                                                                            opacity: 0;
                                                                                                                                                                                                                                                            transform: translateY(-10px);
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                        50% {
                                                                                                                                                                                                                                                            opacity: 1;
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                        100% {
                                                                                                                                                                                                                                                            opacity: 0;
                                                                                                                                                                                                                                                            transform: translateY(10px);
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                    .badge-2 {
                                                                                                                                                                                                                                                        bottom: 30px;
                                                                                                                                                                                                                                                        right: -20px;
                                                                                                                                                                                                                                                        animation-delay: 2s;

                                                                                                                                                                                                                                                        /* ── 12. STATS BAR ───────────────────────────────────────────────── */
                                                                                                                                                                                                                                                        .stats-bar {
                                                                                                                                                                                                                                                            background: var(--bg-card);
                                                                                                                                                                                                                                                            border-top: 1px solid var(--border);
                                                                                                                                                                                                                                                            border-bottom: 1px solid var(--border);
                                                                                                                                                                                                                                                            padding: 40px 0;
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                        @keyframes floatAnim {

                                                                                                                                                                                                                                                            0%,
                                                                                                                                                                                                                                                            100% {
                                                                                                                                                                                                                                                                transform: translateY(0);
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                            50% {
                                                                                                                                                                                                                                                                transform: translateY(-8px);
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                            .stats-grid {
                                                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                justify-content: center;
                                                                                                                                                                                                                                                                gap: 0;
                                                                                                                                                                                                                                                                flex-wrap: wrap;
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                            /* 8. SECTION HEADER & CARDS */
                                                                                                                                                                                                                                                            .section-header {
                                                                                                                                                                                                                                                                margin-bottom: 45px;

                                                                                                                                                                                                                                                                .stat-block {
                                                                                                                                                                                                                                                                    flex: 1;
                                                                                                                                                                                                                                                                    min-width: 160px;
                                                                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                                                                    flex-direction: column;
                                                                                                                                                                                                                                                                    align-items: center;
                                                                                                                                                                                                                                                                    gap: 4px;
                                                                                                                                                                                                                                                                    padding: 20px;
                                                                                                                                                                                                                                                                    animation-delay: var(--delay, 0s);
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                .section-header.text-center {
                                                                                                                                                                                                                                                                    text-align: center;

                                                                                                                                                                                                                                                                    .stat-val {
                                                                                                                                                                                                                                                                        font-family: var(--font-head);
                                                                                                                                                                                                                                                                        font-size: 3rem;
                                                                                                                                                                                                                                                                        font-weight: 800;
                                                                                                                                                                                                                                                                        color: var(--text-white);
                                                                                                                                                                                                                                                                        line-height: 1;
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    .stat-unit {
                                                                                                                                                                                                                                                                        font-size: 1.4rem;
                                                                                                                                                                                                                                                                        font-weight: 700;
                                                                                                                                                                                                                                                                        color: var(--cyan);
                                                                                                                                                                                                                                                                        margin-top: -8px;
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    .stat-lbl {
                                                                                                                                                                                                                                                                        font-size: 13px;
                                                                                                                                                                                                                                                                        color: var(--text-muted);
                                                                                                                                                                                                                                                                        text-align: center;
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    .stat-sep {
                                                                                                                                                                                                                                                                        width: 1px;
                                                                                                                                                                                                                                                                        height: 50px;
                                                                                                                                                                                                                                                                        background: var(--border);
                                                                                                                                                                                                                                                                        flex-shrink: 0;
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    .sub-badge {
                                                                                                                                                                                                                                                                        display: inline-block;
                                                                                                                                                                                                                                                                        font-size: 12px;
                                                                                                                                                                                                                                                                        font-weight: 700;
                                                                                                                                                                                                                                                                        text-transform: uppercase;
                                                                                                                                                                                                                                                                        letter-spacing: 1.5px;
                                                                                                                                                                                                                                                                        color: var(--color-cyan-glow);
                                                                                                                                                                                                                                                                        background: rgba(30, 58, 138, 0.3);
                                                                                                                                                                                                                                                                        border: 1px solid rgba(56, 189, 248, 0.25);
                                                                                                                                                                                                                                                                        padding: 4px 14px;
                                                                                                                                                                                                                                                                        border-radius: 20px;
                                                                                                                                                                                                                                                                        margin-bottom: 12px;
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    /* ── 13. SECTION BLOCKS ─────────────────────────────────────────── */
                                                                                                                                                                                                                                                                    .section-block {
                                                                                                                                                                                                                                                                        padding: 80px 0;
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    .section-block.alt-bg {
                                                                                                                                                                                                                                                                        background: var(--bg-alt);
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    .section-title {
                                                                                                                                                                                                                                                                        font-size: 2.2rem;
                                                                                                                                                                                                                                                                        font-weight: 800;
                                                                                                                                                                                                                                                                        letter-spacing: -0.5px;
                                                                                                                                                                                                                                                                        margin-bottom: 12px;

                                                                                                                                                                                                                                                                        /* ── 14. PILLAR CARDS (HOME 3 PILAR) ──────────────────────────── */
                                                                                                                                                                                                                                                                        .pillar-grid {
                                                                                                                                                                                                                                                                            display: grid;
                                                                                                                                                                                                                                                                            grid-template-columns: repeat(3, 1fr);
                                                                                                                                                                                                                                                                            gap: 24px;
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        .section-subtitle {
                                                                                                                                                                                                                                                                            font-size: 1.05rem;
                                                                                                                                                                                                                                                                            color: var(--color-gray-muted);
                                                                                                                                                                                                                                                                            max-width: 720px;
                                                                                                                                                                                                                                                                            margin: 0 auto;

                                                                                                                                                                                                                                                                            .pillar-card {
                                                                                                                                                                                                                                                                                background: var(--bg-card);
                                                                                                                                                                                                                                                                                border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                border-radius: var(--r-xl);
                                                                                                                                                                                                                                                                                padding: 36px 30px;
                                                                                                                                                                                                                                                                                position: relative;
                                                                                                                                                                                                                                                                                overflow: hidden;
                                                                                                                                                                                                                                                                                transition: all var(--t-med);
                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                            /* Glow Card Style */
                                                                                                                                                                                                                                                                            .glow-card {
                                                                                                                                                                                                                                                                                background: rgba(19, 27, 46, 0.75);
                                                                                                                                                                                                                                                                                backdrop-filter: blur(10px);
                                                                                                                                                                                                                                                                                border: 1px solid rgba(148, 163, 184, 0.12);
                                                                                                                                                                                                                                                                                border-radius: 18px;
                                                                                                                                                                                                                                                                                padding: 30px;
                                                                                                                                                                                                                                                                                transition: all var(--transition-smooth);
                                                                                                                                                                                                                                                                                position: relative;
                                                                                                                                                                                                                                                                                overflow: hidden;

                                                                                                                                                                                                                                                                                .pillar-card::before {
                                                                                                                                                                                                                                                                                    content: '';
                                                                                                                                                                                                                                                                                    position: absolute;
                                                                                                                                                                                                                                                                                    top: 0;
                                                                                                                                                                                                                                                                                    left: 0;
                                                                                                                                                                                                                                                                                    right: 0;
                                                                                                                                                                                                                                                                                    height: 3px;
                                                                                                                                                                                                                                                                                    background: linear-gradient(90deg, var(--blue-700), var(--cyan));
                                                                                                                                                                                                                                                                                    opacity: 0;
                                                                                                                                                                                                                                                                                    transition: opacity var(--t-fast);
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                .pillar-card:hover {
                                                                                                                                                                                                                                                                                    transform: translateY(-6px);
                                                                                                                                                                                                                                                                                    border-color: var(--border-blue);
                                                                                                                                                                                                                                                                                    box-shadow: var(--shadow-glow);
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                .pillar-card:hover::before {
                                                                                                                                                                                                                                                                                    opacity: 1;
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                .glow-card:hover {
                                                                                                                                                                                                                                                                                    transform: translateY(-5px);
                                                                                                                                                                                                                                                                                    border-color: rgba(56, 189, 248, 0.4);
                                                                                                                                                                                                                                                                                    box-shadow: var(--glow-card-hover);

                                                                                                                                                                                                                                                                                    .pillar-featured {
                                                                                                                                                                                                                                                                                        background: linear-gradient(135deg, var(--blue-900), var(--bg-card-alt));
                                                                                                                                                                                                                                                                                        border-color: var(--border-blue);
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                    /* Overview 3 Pilar di Home */
                                                                                                                                                                                                                                                                                    .home-services-overview {
                                                                                                                                                                                                                                                                                        padding: 60px 0 50px;

                                                                                                                                                                                                                                                                                        .pillar-featured::before {
                                                                                                                                                                                                                                                                                            opacity: 1;
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                        .pc-badge {
                                                                                                                                                                                                                                                                                            position: absolute;
                                                                                                                                                                                                                                                                                            top: 16px;
                                                                                                                                                                                                                                                                                            right: 16px;
                                                                                                                                                                                                                                                                                            font-size: 11px;
                                                                                                                                                                                                                                                                                            font-weight: 700;
                                                                                                                                                                                                                                                                                            color: var(--cyan);
                                                                                                                                                                                                                                                                                            background: var(--cyan-dim);
                                                                                                                                                                                                                                                                                            border: 1px solid var(--border-blue);
                                                                                                                                                                                                                                                                                            padding: 3px 10px;
                                                                                                                                                                                                                                                                                            border-radius: 999px;
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                        .overview-grid {
                                                                                                                                                                                                                                                                                            display: grid;
                                                                                                                                                                                                                                                                                            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
                                                                                                                                                                                                                                                                                            gap: 25px;

                                                                                                                                                                                                                                                                                            .pc-num {
                                                                                                                                                                                                                                                                                                font-family: var(--font-head);
                                                                                                                                                                                                                                                                                                font-size: 3rem;
                                                                                                                                                                                                                                                                                                font-weight: 800;
                                                                                                                                                                                                                                                                                                color: rgba(0, 212, 255, 0.08);
                                                                                                                                                                                                                                                                                                line-height: 1;
                                                                                                                                                                                                                                                                                                margin-bottom: 16px;
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                            .overview-card .card-icon {
                                                                                                                                                                                                                                                                                                width: 60px;
                                                                                                                                                                                                                                                                                                height: 60px;
                                                                                                                                                                                                                                                                                                border-radius: 14px;
                                                                                                                                                                                                                                                                                                background: linear-gradient(135deg, var(--color-navy-dark), var(--color-navy-light));
                                                                                                                                                                                                                                                                                                border: 1px solid rgba(56, 189, 248, 0.3);
                                                                                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                justify-content: center;
