                                                                                                                                                                                                                                                                                                            margin-bottom: 24px;
                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                        .pc-link {
                                                                                                                                                                                                                                                                                                            font-size: 14px;
                                                                                                                                                                                                                                                                                                            font-weight: 700;
                                                                                                                                                                                                                                                                                                            color: var(--cyan);
                                                                                                                                                                                                                                                                                                            display: inline-flex;
                                                                                                                                                                                                                                                                                                            align-items: center;
                                                                                                                                                                                                                                                                                                            gap: 8px;
