                                                                                                                                                                                                                                                                                                            margin-bottom: 24px;
                                                                                                                                                                                                                                                                                                            line-height: 1.6;

                                                                                                                                                                                                                                                                                                            /* ── 15. WHY US SECTION ─────────────────────────────────────────── */
                                                                                                                                                                                                                                                                                                            .why-grid {
                                                                                                                                                                                                                                                                                                                display: grid;
                                                                                                                                                                                                                                                                                                                grid-template-columns: 0.8fr 1.2fr;
                                                                                                                                                                                                                                                                                                                gap: 80px;
                                                                                                                                                                                                                                                                                                                align-items: start;
                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                            .card-link {
                                                                                                                                                                                                                                                                                                                background: transparent;
                                                                                                                                                                                                                                                                                                                border: none;
                                                                                                                                                                                                                                                                                                                color: var(--color-cyan-glow);
                                                                                                                                                                                                                                                                                                                font-size: 14px;
                                                                                                                                                                                                                                                                                                                font-weight: 700;
                                                                                                                                                                                                                                                                                                                display: inline-flex;
                                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                                gap: 8px;
                                                                                                                                                                                                                                                                                                                padding: 0;

                                                                                                                                                                                                                                                                                                                .why-item {
                                                                                                                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                                                                                                                    gap: 20px;
                                                                                                                                                                                                                                                                                                                    padding: 24px;
                                                                                                                                                                                                                                                                                                                    border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                    border-radius: var(--r-lg);
                                                                                                                                                                                                                                                                                                                    margin-bottom: 16px;
                                                                                                                                                                                                                                                                                                                    background: var(--bg-card);
                                                                                                                                                                                                                                                                                                                    transition: all var(--t-fast);
                                                                                                                                                                                                                                                                                                                    animation-delay: var(--delay, 0s);
                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                .card-link:hover {
                                                                                                                                                                                                                                                                                                                    gap: 12px;

                                                                                                                                                                                                                                                                                                                    .why-item:hover {
                                                                                                                                                                                                                                                                                                                        border-color: var(--border-blue);
                                                                                                                                                                                                                                                                                                                        transform: translateX(6px);
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                    .wi-icon {
                                                                                                                                                                                                                                                                                                                        width: 48px;
                                                                                                                                                                                                                                                                                                                        height: 48px;
                                                                                                                                                                                                                                                                                                                        border-radius: 12px;
                                                                                                                                                                                                                                                                                                                        flex-shrink: 0;
                                                                                                                                                                                                                                                                                                                        background: var(--cyan-dim);
                                                                                                                                                                                                                                                                                                                        border: 1px solid var(--border-blue);
                                                                                                                                                                                                                                                                                                                        display: flex;
                                                                                                                                                                                                                                                                                                                        align-items: center;
                                                                                                                                                                                                                                                                                                                        justify-content: center;
                                                                                                                                                                                                                                                                                                                        font-size: 20px;
                                                                                                                                                                                                                                                                                                                        color: var(--cyan);
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                    .wi-icon.wi-gold {
                                                                                                                                                                                                                                                                                                                        background: var(--gold-dim);
                                                                                                                                                                                                                                                                                                                        color: var(--gold);
                                                                                                                                                                                                                                                                                                                        border-color: rgba(245, 158, 11, 0.3);
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                    .wi-icon.wi-green {
                                                                                                                                                                                                                                                                                                                        background: var(--green-dim);
                                                                                                                                                                                                                                                                                                                        color: var(--green);
                                                                                                                                                                                                                                                                                                                        border-color: rgba(34, 197, 94, 0.3);
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                    .wi-icon.wi-purple {
                                                                                                                                                                                                                                                                                                                        background: var(--purple-dim);
                                                                                                                                                                                                                                                                                                                        color: var(--purple);
