                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                    .wi-text h4 {
                                                                                                                                                                                                                                                                                                                        font-size: 1rem;
                                                                                                                                                                                                                                                                                                                        color: var(--text-white);
                                                                                                                                                                                                                                                                                                                        margin-bottom: 6px;
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                    .wi-text p {
                                                                                                                                                                                                                                                                                                                        font-size: 13.5px;
                                                                                                                                                                                                                                                                                                                        color: var(--text-secondary);
                                                                                                                                                                                                                                                                                                                        line-height: 1.6;
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                    /* Features Grid */
                                                                                                                                                                                                                                                                                                                    .features-section {
                                                                                                                                                                                                                                                                                                                        padding: 50px 0 60px;

                                                                                                                                                                                                                                                                                                                        /* ── 16. TESTI STRIP ───────────────────────────────────────────── */
                                                                                                                                                                                                                                                                                                                        .testi-strip {
                                                                                                                                                                                                                                                                                                                            background: linear-gradient(135deg, var(--blue-900), var(--bg-card));
                                                                                                                                                                                                                                                                                                                            border-top: 1px solid var(--border-blue);
                                                                                                                                                                                                                                                                                                                            border-bottom: 1px solid var(--border-blue);
                                                                                                                                                                                                                                                                                                                            padding: 50px 0;
                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                        .features-grid {
                                                                                                                                                                                                                                                                                                                            display: grid;
                                                                                                                                                                                                                                                                                                                            grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
                                                                                                                                                                                                                                                                                                                            gap: 20px;

                                                                                                                                                                                                                                                                                                                            .ts-row {
                                                                                                                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                                                gap: 28px;
                                                                                                                                                                                                                                                                                                                                flex-wrap: wrap;
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                            .feature-card {
                                                                                                                                                                                                                                                                                                                                background: rgba(15, 23, 42, 0.6);
                                                                                                                                                                                                                                                                                                                                border: 1px solid rgba(148, 163, 184, 0.1);
                                                                                                                                                                                                                                                                                                                                padding: 24px;
                                                                                                                                                                                                                                                                                                                                border-radius: 14px;
                                                                                                                                                                                                                                                                                                                                transition: all var(--transition-smooth);

                                                                                                                                                                                                                                                                                                                                .ts-quote {
                                                                                                                                                                                                                                                                                                                                    font-size: 3rem;
                                                                                                                                                                                                                                                                                                                                    color: var(--cyan);
                                                                                                                                                                                                                                                                                                                                    opacity: 0.4;
                                                                                                                                                                                                                                                                                                                                    flex-shrink: 0;
                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                .ts-text {
                                                                                                                                                                                                                                                                                                                                    flex: 1;
                                                                                                                                                                                                                                                                                                                                    min-width: 260px;
                                                                                                                                                                                                                                                                                                                                    font-size: 1.15rem;
                                                                                                                                                                                                                                                                                                                                    color: var(--text-white);
                                                                                                                                                                                                                                                                                                                                    font-style: italic;
                                                                                                                                                                                                                                                                                                                                    line-height: 1.7;
                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                .feature-card:hover {
                                                                                                                                                                                                                                                                                                                                    border-color: rgba(56, 189, 248, 0.3);
                                                                                                                                                                                                                                                                                                                                    transform: translateY(-3px);

                                                                                                                                                                                                                                                                                                                                    .ts-author {
                                                                                                                                                                                                                                                                                                                                        display: flex;
                                                                                                                                                                                                                                                                                                                                        align-items: center;
                                                                                                                                                                                                                                                                                                                                        gap: 14px;
                                                                                                                                                                                                                                                                                                                                        flex-shrink: 0;
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                    .ts-avatar {
                                                                                                                                                                                                                                                                                                                                        width: 48px;
                                                                                                                                                                                                                                                                                                                                        height: 48px;
                                                                                                                                                                                                                                                                                                                                        border-radius: 50%;
                                                                                                                                                                                                                                                                                                                                        background: var(--blue-800);
                                                                                                                                                                                                                                                                                                                                        border: 1px solid var(--border-blue);
                                                                                                                                                                                                                                                                                                                                        display: flex;
                                                                                                                                                                                                                                                                                                                                        align-items: center;
                                                                                                                                                                                                                                                                                                                                        justify-content: center;
                                                                                                                                                                                                                                                                                                                                        font-size: 20px;
                                                                                                                                                                                                                                                                                                                                        color: var(--cyan);
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                    .ts-author strong {
                                                                                                                                                                                                                                                                                                                                        display: block;
                                                                                                                                                                                                                                                                                                                                        font-size: 14px;
                                                                                                                                                                                                                                                                                                                                        color: var(--text-white);
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                    .ts-author span {
                                                                                                                                                                                                                                                                                                                                        font-size: 12px;
                                                                                                                                                                                                                                                                                                                                        color: var(--text-muted);
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                    .feature-icon {
                                                                                                                                                                                                                                                                                                                                        font-size: 26px;
                                                                                                                                                                                                                                                                                                                                        color: var(--color-cyan-glow);
                                                                                                                                                                                                                                                                                                                                        margin-bottom: 15px;

                                                                                                                                                                                                                                                                                                                                        /* ── 17. PAGE NAV BOTTOM ───────────────────────────────────────── */
                                                                                                                                                                                                                                                                                                                                        .page-nav-bottom {
                                                                                                                                                                                                                                                                                                                                            margin-top: 60px;
                                                                                                                                                                                                                                                                                                                                            padding: 24px 30px;
                                                                                                                                                                                                                                                                                                                                            background: var(--bg-card);
                                                                                                                                                                                                                                                                                                                                            border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                                            border-radius: var(--r-xl);
                                                                                                                                                                                                                                                                                                                                            box-shadow: 0 -4px 30px rgba(0, 0, 0, 0.3);
                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                        .feature-card h4 {
                                                                                                                                                                                                                                                                                                                                            font-size: 1.1rem;
                                                                                                                                                                                                                                                                                                                                            margin-bottom: 10px;

                                                                                                                                                                                                                                                                                                                                            .pnb-flex {
                                                                                                                                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                                                                justify-content: space-between;
                                                                                                                                                                                                                                                                                                                                                gap: 20px;
                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                            .pnb-info {
                                                                                                                                                                                                                                                                                                                                                font-size: 13px;
                                                                                                                                                                                                                                                                                                                                                color: var(--text-muted);
                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                            .feature-card p {
                                                                                                                                                                                                                                                                                                                                                font-size: 13.5px;
                                                                                                                                                                                                                                                                                                                                                color: var(--color-gray-muted);

                                                                                                                                                                                                                                                                                                                                                .btn-next-page {
                                                                                                                                                                                                                                                                                                                                                    display: inline-flex;
                                                                                                                                                                                                                                                                                                                                                    align-items: center;
                                                                                                                                                                                                                                                                                                                                                    gap: 10px;
                                                                                                                                                                                                                                                                                                                                                    background: linear-gradient(135deg, var(--blue-900), var(--blue-700));
                                                                                                                                                                                                                                                                                                                                                    color: var(--text-white);
                                                                                                                                                                                                                                                                                                                                                    font-size: 14px;
                                                                                                                                                                                                                                                                                                                                                    font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                    padding: 12px 24px;
                                                                                                                                                                                                                                                                                                                                                    border-radius: 10px;
                                                                                                                                                                                                                                                                                                                                                    border: 1px solid var(--border-blue);
                                                                                                                                                                                                                                                                                                                                                    transition: all var(--t-fast);
                                                                                                                                                                                                                                                                                                                                                    cursor: pointer;
                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                /* 9. HALAMAN LAYANAN (DETAIL LENGKAP) */
                                                                                                                                                                                                                                                                                                                                                .service-detail-row {
                                                                                                                                                                                                                                                                                                                                                    display: grid;
                                                                                                                                                                                                                                                                                                                                                    grid-template-columns: 1fr 1.25fr;
                                                                                                                                                                                                                                                                                                                                                    gap: 45px;
                                                                                                                                                                                                                                                                                                                                                    align-items: center;
                                                                                                                                                                                                                                                                                                                                                    background: rgba(19, 27, 46, 0.5);
                                                                                                                                                                                                                                                                                                                                                    border: 1px solid rgba(148, 163, 184, 0.1);
                                                                                                                                                                                                                                                                                                                                                    border-radius: 20px;
                                                                                                                                                                                                                                                                                                                                                    padding: 35px;
                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 35px;
                                                                                                                                                                                                                                                                                                                                                    transition: all var(--transition-smooth);

                                                                                                                                                                                                                                                                                                                                                    .btn-next-page:hover {
                                                                                                                                                                                                                                                                                                                                                        transform: translateY(-2px);
                                                                                                                                                                                                                                                                                                                                                        box-shadow: 0 8px 24px rgba(26, 86, 219, 0.4), 0 0 20px var(--cyan-glow);
                                                                                                                                                                                                                                                                                                                                                        border-color: var(--border-hover);
                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                    .service-detail-row:hover {
                                                                                                                                                                                                                                                                                                                                                        border-color: rgba(56, 189, 248, 0.3);
                                                                                                                                                                                                                                                                                                                                                        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);

                                                                                                                                                                                                                                                                                                                                                        .btn-prev-page {
                                                                                                                                                                                                                                                                                                                                                            display: inline-flex;
                                                                                                                                                                                                                                                                                                                                                            align-items: center;
                                                                                                                                                                                                                                                                                                                                                            gap: 10px;
                                                                                                                                                                                                                                                                                                                                                            background: rgba(255, 255, 255, 0.04);
                                                                                                                                                                                                                                                                                                                                                            color: var(--text-secondary);
                                                                                                                                                                                                                                                                                                                                                            font-size: 14px;
                                                                                                                                                                                                                                                                                                                                                            font-weight: 600;
                                                                                                                                                                                                                                                                                                                                                            padding: 12px 20px;
                                                                                                                                                                                                                                                                                                                                                            border-radius: 10px;
                                                                                                                                                                                                                                                                                                                                                            border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                                                            transition: all var(--t-fast);
                                                                                                                                                                                                                                                                                                                                                            cursor: pointer;
                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                        .btn-prev-page:hover {
                                                                                                                                                                                                                                                                                                                                                            background: rgba(255, 255, 255, 0.08);
                                                                                                                                                                                                                                                                                                                                                            color: var(--text-white);
                                                                                                                                                                                                                                                                                                                                                            border-color: var(--cyan);
                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                        .service-detail-row.reverse {
                                                                                                                                                                                                                                                                                                                                                            grid-template-columns: 1.25fr 1fr;

                                                                                                                                                                                                                                                                                                                                                            /* ── 18. SERVICE DETAIL ROWS ──────────────────────────────────── */
                                                                                                                                                                                                                                                                                                                                                            .svc-row {
                                                                                                                                                                                                                                                                                                                                                                display: grid;
                                                                                                                                                                                                                                                                                                                                                                grid-template-columns: 0.9fr 1.1fr;
                                                                                                                                                                                                                                                                                                                                                                gap: 50px;
                                                                                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                                                                                background: var(--bg-card);
                                                                                                                                                                                                                                                                                                                                                                border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                                                                border-radius: var(--r-xl);
                                                                                                                                                                                                                                                                                                                                                                padding: 40px;
                                                                                                                                                                                                                                                                                                                                                                margin-bottom: 30px;
                                                                                                                                                                                                                                                                                                                                                                transition: all var(--t-med);
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                            .svc-row:hover {
                                                                                                                                                                                                                                                                                                                                                                border-color: var(--border-blue);
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                            .svc-row-rev {
                                                                                                                                                                                                                                                                                                                                                                grid-template-columns: 1.1fr 0.9fr;
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                            .svc-row-rev .svc-visual {
                                                                                                                                                                                                                                                                                                                                                                order: 2;
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                            .svc-row-rev .svc-info {
                                                                                                                                                                                                                                                                                                                                                                order: 1;
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                            .service-detail-row.reverse .service-media {
                                                                                                                                                                                                                                                                                                                                                                order: 2;

                                                                                                                                                                                                                                                                                                                                                                .glow-box {
                                                                                                                                                                                                                                                                                                                                                                    border-radius: var(--r-lg);
                                                                                                                                                                                                                                                                                                                                                                    overflow: hidden;
                                                                                                                                                                                                                                                                                                                                                                    position: relative;
                                                                                                                                                                                                                                                                                                                                                                    border: 1px solid var(--border-blue);
                                                                                                                                                                                                                                                                                                                                                                    box-shadow: var(--shadow-card), 0 0 30px rgba(0, 212, 255, 0.1);
                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                .service-detail-row.reverse .service-info {
                                                                                                                                                                                                                                                                                                                                                                    order: 1;

                                                                                                                                                                                                                                                                                                                                                                    .glow-box img {
                                                                                                                                                                                                                                                                                                                                                                        width: 100%;
                                                                                                                                                                                                                                                                                                                                                                        height: 300px;
                                                                                                                                                                                                                                                                                                                                                                        object-fit: cover;
                                                                                                                                                                                                                                                                                                                                                                        display: block;
                                                                                                                                                                                                                                                                                                                                                                        transition: transform 0.5s var(--ease);
                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                    .service-media {
                                                                                                                                                                                                                                                                                                                                                                        position: relative;
                                                                                                                                                                                                                                                                                                                                                                        border-radius: 16px;
                                                                                                                                                                                                                                                                                                                                                                        overflow: hidden;

                                                                                                                                                                                                                                                                                                                                                                        .svc-row:hover .glow-box img {
                                                                                                                                                                                                                                                                                                                                                                            transform: scale(1.04);
                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                        .svc-visual-badge {
                                                                                                                                                                                                                                                                                                                                                                            position: absolute;
                                                                                                                                                                                                                                                                                                                                                                            top: 14px;
                                                                                                                                                                                                                                                                                                                                                                            left: 14px;
                                                                                                                                                                                                                                                                                                                                                                            font-size: 12px;
                                                                                                                                                                                                                                                                                                                                                                            font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                                            color: var(--cyan);
                                                                                                                                                                                                                                                                                                                                                                            background: rgba(6, 13, 26, 0.9);
                                                                                                                                                                                                                                                                                                                                                                            border: 1px solid var(--border-blue);
                                                                                                                                                                                                                                                                                                                                                                            padding: 4px 12px;
