                                                                                                                                                                                                                                                                                                                                                                                                                                        align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                        gap: 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                        font-size: 14px;
                                                                                                                                                                                                                                                                                                                                                                                                                                        color: var(--text-secondary);
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                    .price-features li i {
                                                                                                                                                                                                                                                                                                                                                                                                                                        font-size: 14px;
                                                                                                                                                                                                                                                                                                                                                                                                                                        flex-shrink: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                    .price-features li i.fa-check {
                                                                                                                                                                                                                                                                                                                                                                                                                                        color: var(--green);
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                    .price-features li.price-no {
                                                                                                                                                                                                                                                                                                                                                                                                                                        opacity: 0.4;
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                    .price-features li.price-no i {
                                                                                                                                                                                                                                                                                                                                                                                                                                        color: var(--text-muted);
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                    .maintenance-cta {
                                                                                                                                                                                                                                                                                                                                                                                                                                        flex-shrink: 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                        .btn-price-cta {
                                                                                                                                                                                                                                                                                                                                                                                                                                            display: block;
                                                                                                                                                                                                                                                                                                                                                                                                                                            text-align: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                            font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                                                                                                            font-size: 14.5px;
                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: 13px;
                                                                                                                                                                                                                                                                                                                                                                                                                                            border-radius: 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                            background: rgba(255, 255, 255, 0.05);
                                                                                                                                                                                                                                                                                                                                                                                                                                            color: var(--text-white);
                                                                                                                                                                                                                                                                                                                                                                                                                                            border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                                                                                                                                            transition: all var(--t-fast);
                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                        /* Workflow Steps */
                                                                                                                                                                                                                                                                                                                                                                                                                                        .workflow-section {
                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: 30px 0 50px;

                                                                                                                                                                                                                                                                                                                                                                                                                                            .btn-price-cta:hover {
                                                                                                                                                                                                                                                                                                                                                                                                                                                background: var(--blue-700);
                                                                                                                                                                                                                                                                                                                                                                                                                                                border-color: var(--blue-700);
                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                            .btn-price-featured {
                                                                                                                                                                                                                                                                                                                                                                                                                                                background: linear-gradient(135deg, var(--blue-700), var(--cyan));
                                                                                                                                                                                                                                                                                                                                                                                                                                                border-color: transparent;
                                                                                                                                                                                                                                                                                                                                                                                                                                                color: #fff;
                                                                                                                                                                                                                                                                                                                                                                                                                                                box-shadow: 0 6px 20px rgba(26, 86, 219, 0.5);
                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                            .workflow-steps {
                                                                                                                                                                                                                                                                                                                                                                                                                                                display: grid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
                                                                                                                                                                                                                                                                                                                                                                                                                                                gap: 20px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                /* Notice Box */
                                                                                                                                                                                                                                                                                                                                                                                                                                                .notice-box {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    align-items: flex-start;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    gap: 14px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: var(--bg-card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    border-radius: var(--r-md);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: 20px 24px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 14px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: var(--text-secondary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                .notice-box i {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: var(--cyan);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 18px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    flex-shrink: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin-top: 2px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                .notice-box strong {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: var(--text-white);
                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                .step-card {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: rgba(15, 23, 42, 0.6);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    border: 1px solid rgba(148, 163, 184, 0.1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    border-radius: 16px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: 25px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    position: relative;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    transition: all var(--transition-smooth);

                                                                                                                                                                                                                                                                                                                                                                                                                                                    /* Compare Table */
                                                                                                                                                                                                                                                                                                                                                                                                                                                    .compare-table-wrap {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        overflow-x: auto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    .compare-table {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        width: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        border-collapse: collapse;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        background: var(--bg-card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                        border-radius: var(--r-xl);
                                                                                                                                                                                                                                                                                                                                                                                                                                                        overflow: hidden;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    .step-card:hover {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        border-color: var(--color-cyan-glow);
                                                                                                                                                                                                                                                                                                                                                                                                                                                        transform: translateY(-4px);

                                                                                                                                                                                                                                                                                                                                                                                                                                                        .compare-table th,
                                                                                                                                                                                                                                                                                                                                                                                                                                                        .compare-table td {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: 14px 20px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            text-align: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            font-size: 14px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            border-bottom: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                        .step-num {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            width: 36px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            height: 36px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            border-radius: 50%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            background: var(--color-navy-light);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            color: var(--color-cyan-glow);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            border: 1px solid rgba(56, 189, 248, 0.4);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            justify-content: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            font-weight: 800;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            margin-bottom: 15px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            box-shadow: 0 0 10px rgba(56, 189, 248, 0.3);

                                                                                                                                                                                                                                                                                                                                                                                                                                                            .compare-table th {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: var(--text-white);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: var(--bg-card-alt);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-size: 13px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                text-transform: uppercase;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                letter-spacing: 0.5px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            .compare-table th:first-child,
                                                                                                                                                                                                                                                                                                                                                                                                                                                            .compare-table td:first-child {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                text-align: left;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: var(--text-secondary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            .th-featured {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: var(--blue-900) !important;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: var(--cyan) !important;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            .compare-table tr:hover td {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: rgba(255, 255, 255, 0.02);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            .compare-table td {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: var(--text-secondary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            .ct-yes {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: var(--green);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-size: 16px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            .ct-no {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: var(--text-muted);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-size: 16px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            .step-card h4 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-size: 1.15rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                margin-bottom: 8px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                /* ── 22. PORTFOLIO ───────────────────────────────────────────────── */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                .filter-tabs {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    gap: 8px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 36px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    flex-wrap: wrap;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                .ftab {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 13px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-weight: 600;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: var(--text-secondary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: var(--bg-card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: 8px 20px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border-radius: 999px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cursor: pointer;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    transition: all var(--t-fast);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                .step-card p {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 13.5px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: var(--color-gray-muted);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .ftab.active,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .ftab:hover {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        background: var(--blue-700);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        color: #fff;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border-color: var(--blue-700);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /* 10. HALAMAN PORTOFOLIO (PROYEK SURAKARTA) */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .portfolio-grid {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        display: grid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gap: 30px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        margin-bottom: 60px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        display: grid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        grid-template-columns: repeat(2, 1fr);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gap: 24px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        margin-bottom: 60px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .portfolio-card {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        overflow: hidden;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .port-card {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            background: var(--bg-card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border-radius: var(--r-xl);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            overflow: hidden;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            transition: all var(--t-med);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .portfolio-img-box {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            position: relative;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            height: 240px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            overflow: hidden;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .port-card:hover {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                transform: translateY(-5px);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border-color: var(--border-blue);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                box-shadow: var(--shadow-glow);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .port-img {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                position: relative;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                height: 260px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                overflow: hidden;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .port-img img {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                width: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                height: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                object-fit: cover;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                transition: transform 0.5s var(--ease);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .port-card:hover .port-img img {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                transform: scale(1.06);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .port-overlay {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                position: absolute;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                inset: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: linear-gradient(to top, rgba(6, 13, 26, 0.95), rgba(6, 13, 26, 0.4) 50%, transparent);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                justify-content: flex-end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: 24px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                opacity: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                transition: opacity var(--t-fast);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .portfolio-img-box img {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                width: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                height: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                object-fit: cover;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                display: block;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                transition: transform 0.5s ease;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .port-card:hover .port-overlay {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    opacity: 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .port-cat {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 12px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: var(--cyan);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: var(--cyan-dim);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: 3px 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border-radius: 999px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border: 1px solid var(--border-blue);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 8px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    align-self: flex-start;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .port-overlay h4 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 1.1rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: var(--text-white);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 6px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .port-overlay p {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 13px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: var(--text-secondary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .portfolio-card:hover .portfolio-img-box img {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    transform: scale(1.06);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .port-meta {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: 20px 24px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .port-loc {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        font-size: 13px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        color: var(--cyan);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gap: 6px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        margin-bottom: 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .port-tags {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gap: 8px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        flex-wrap: wrap;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .port-tags span {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        font-size: 12px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        color: var(--text-secondary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        background: var(--bg-surface);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: 4px 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border-radius: 6px;
