                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /* ── 23. TEAM PAGE ──────────────────────────────────────────────── */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .team-grid {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    display: grid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    grid-template-columns: repeat(2, 1fr);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    gap: 24px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 60px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .portfolio-body h3 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 1.25rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin-bottom: 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    line-height: 1.35;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .team-card {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        background: var(--bg-card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border: 1px solid var(--border);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border-radius: var(--r-xl);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: 36px;
