                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gap: 28px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        transition: all var(--t-med);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        position: relative;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        overflow: hidden;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .portfolio-body p {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        font-size: 14px;
