                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .team-card::after {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            content: '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            position: absolute;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            top: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            left: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            right: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            height: 3px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            background: linear-gradient(90deg, var(--blue-700), var(--cyan));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            opacity: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            transition: opacity var(--t-fast);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .team-card:hover {
