                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                gap: 6px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .team-card-alt .team-av-inner {
